-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ptBR" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.hunter.ranged.Name"] = "À distância"
L["rm.era.hunter.ranged.Description"] = "Todo Caçador do nível 1 ao 60, todas as árvores de talentos. Puxa com Marca do Caçador, Tiro Certo e Tiro Automático. Solo, o ajudante tanqueia: sua própria Picada de Serpente, depois Tiro Certo, Tiro Arcano e Tiro Múltiplo só enquanto a mana estiver acima da metade, Tiro de Concussão para fazer kiting antes de você ter um ajudante. Em grupo, Tiro Certo e Tiro Múltiplo logo após um Tiro Automático para que ele nunca atrase, Picada de Serpente fora de raides, Tiro Arcano só antes de Tiro Certo ou em um alvo morrendo. Botões corpo a corpo quando um inimigo está perto demais, instantâneos em movimento, Tiro Múltiplo e Salva contra três ou mais inimigos. Lembretes: Falcão (Macaco antes dele), Aura de Tiro Certeiro, cuidados com o ajudante, Tiro Rápido, Ira Bestial e habilidades raciais em elites e em instâncias, Intimidação e Fingir de Morto. Armadilhas, Cortar Asas, Alimentar Ajudante, Tiro Tranquilizante e o posicionamento ficam com você."
L["rm.era.hunter.ranged.icyveins.Name"] = "À distância, atrasando o Tiro Automático (Icy Veins)"
L["rm.era.hunter.ranged.icyveins.Description"] = "Desativada por padrão; ative-a para uma arma de longo alcance mais rápida que 3,0 segundos. Como Caçador: à distância, mas em grupo Tiro Certo e Tiro Múltiplo saem assim que ficam prontos, mesmo que isso atrase um Tiro Automático, Picada de Serpente nunca é usada, e Tiro Rápido, Ira Bestial e habilidades raciais são usados em toda puxada."
L["rm.era.hunter.ranged.simulator.Name"] = "À distância, Picada de Serpente em raide (simulador)"
L["rm.era.hunter.ranged.simulator.Description"] = "Desativada por padrão; ative-a onde a raide tiver espaço de penalidades para sua picada. Como Caçador: à distância, mas em grupo Picada de Serpente é mantida em todo lugar, inclusive em raides, renovada com menos de 5 segundos enquanto Tiro Certo e Tiro Múltiplo estão ambos em recarga, e Tiro Arcano nunca é usado."
L["rm.forever.hunter.ranged.Name"] = "À distância (Wowhead)"
L["rm.forever.hunter.ranged.Description"] = "Todo Caçador à distância do nível 1 ao 60 (Domínio das Feras, Precisão, e Sobrevivência até Chute de Moa), e o padrão do Caçador no Forever. Puxada: Marca do Caçador, Tiro de Franco-atirador enquanto Matança Veloz durar, Tiro Automático. Depois sua própria Picada de Serpente, Evocar Falcão duas vezes e Tiro Arcano uma vez no tempo de recarga compartilhado (Tiro Arcano sempre que sair do tempo de recarga antes de Evocar Falcão), Tiro de Franco-atirador com Matança Veloz ou em elites, Tiro Certo. Dois ou mais inimigos lutando com você: Tiro Múltiplo em vez de Tiro Certo, Armadilha Explosiva com três perto de você, Salva com cinco. Em movimento: só tiros instantâneos. Um monstro ao alcance corpo a corpo recebe Golpe do Raptor e Mordida de Mangusto. Lembretes: Aspecto do Falcão (Macaco antes dele), Aura de Tiro Certeiro, chamar e reviver o ajudante, Tiro Rápido, Ira Bestial e Fúria Sangrenta em elites ou em masmorras, Intimidação quando um monstro está em você. Comandos do ajudante, alimentação, kiting e Fingir de Morto ficam com você; desative os lembretes do ajudante se você joga com Lobo Solitário. Ela nunca lê sua mana nem a vida de ninguém, que o Forever oculta dos addons, então Marca do Caçador e Picada de Serpente vão em todo alvo e Curar Ajudante fica com você."
L["rm.forever.hunter.ranged.mobalytics.Name"] = "À distância, econômico em mana (Mobalytics)"
L["rm.forever.hunter.ranged.mobalytics.Description"] = "O estilo de evolução de nível econômico em mana da Mobalytics, uma alternativa à rotação integrada à distância da Wowhead recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Mantém sua Picada de Serpente ativa, um Evocar Falcão em campo, Tiro Certo (Tiro Múltiplo contra dois ou mais inimigos), e nunca Tiro Arcano depois de conhecer Evocar Falcão; o segundo Falcão em um alvo com bastante vida fica de fora, pois o Forever oculta a vida do alvo. A mesma puxada, corpo a corpo, movimento e lembretes da rotação integrada da Wowhead."
L["rm.forever.hunter.survival.Name"] = "Sobrevivência corpo a corpo (Wowhead)"
L["rm.forever.hunter.survival.Description"] = "Sobrevivência corpo a corpo com duas armas assim que Sobrevivência é sua árvore de talentos principal com 21 pontos, o nível do Chute de Moa (até lá, a rotação integrada à distância conduz sua evolução de nível, como os guias recomendam). Puxe com Marca do Caçador e Picada de Serpente, depois Mordida de Mangusto, Chute de Moa, Golpe do Raptor e Contra-ataque, com Armadilha Explosiva contra três ou mais inimigos. Fora do alcance corpo a corpo, atira: Picada de Serpente, Tiro Arcano, Tiro Certo, Tiro Automático. Lembretes: Aspecto da Fera, Marca do Caçador (Expor Presa precisa dela), Tiro Rápido e Fúria Sangrenta em elites ou em masmorras, Coibição enquanto você mantém a atenção do alvo, cuidados com o ajudante (a vida fica oculta no Forever, então Curar Ajudante fica com você). Um passo opcional de Armadilha Imolante vem desativado por padrão."
L["rm.forever.hunter.survival.weave.Name"] = "Sobrevivência intercalando com arma de duas mãos (Wowhead)"
L["rm.forever.hunter.survival.weave.Description"] = "O vai e vem da Wowhead para um Caçador de Sobrevivência com arma de duas mãos, uma alternativa à rotação integrada de Sobrevivência corpo a corpo recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Corpo a corpo: Mordida de Mangusto e Golpe do Raptor; quando faltam mais de 2,5 segundos para Golpe do Raptor, Chute de Moa e afaste-se. Fora do alcance corpo a corpo: Picada de Serpente, Tiro Arcano, Tiro Certo e Tiro Automático até Golpe do Raptor estar quase pronto, depois volte. Você faz a movimentação; o RM acompanha sua distância."
L["rm.mop.hunter.beastmastery.Name"] = "Recomendada"
L["rm.mop.hunter.beastmastery.Description"] = "Escolhida automaticamente na especialização Domínio das Feras. Abre com Marca do Caçador e Comando para Matar, depois: Tiro Mortal, Comando para Matar (segurado por um momento quando Ira Bestial está prestes a ficar pronta), Bando de Corvos, Ímpeto do Lince, Fera Atroz e seu tiro do sexto nível de talentos quando escolhido, Fogo Concentrado com cinco acúmulos de Frenesi (ou quatro prestes a expirar), mas não durante Ira Bestial, Picada de Serpente em alvos que vão sobreviver, Disparo da Naja para renová-la, Tiro Arcano com 80 de concentração ou durante Ira Bestial, depois Disparo da Naja (Tiro Firme antes do nível 81). Com dois ou mais inimigos lutando com você, mantém Cutilada da Fera ativa com Tiro Múltiplo, guarda Comando para Matar para a concentração de sobra em grandes grupos de inimigos e sugere Armadilha Explosiva a partir de três. Lembretes: ajudante invocado, revivido e curado, Aspecto do Falcão ou Aspecto da Águia de Ferro, Tiro Retaliatório, Fervor, e Ira Bestial, Tiro Rápido, Sanha e habilidades raciais quando a luta compensar (um elite, uma masmorra ou raide, ou um alvo que vá sobreviver). O posicionamento de armadilhas, Redirecionar, Fingir de Morto e as defesas ficam com você; os lembretes de Exaltação e Coibição vêm desativados por padrão."
L["rm.mop.hunter.marksmanship.Name"] = "Recomendada"
L["rm.mop.hunter.marksmanship.Description"] = "Escolhida automaticamente na especialização Precisão. Pré-lança Tiro Certo, depois: Tiros Firmes em pares para manter Concentração Firme ativa (a partir do nível 63), Tiro Quimérico, Picada de Serpente em alvos que vão sobreviver, Tiro Certo sempre que Fogo! o tornar instantâneo, Tiro Mortal, seus talentos, e um Tiro Certo lançado normalmente enquanto o alvo estiver acima de 80% de vida, sob Tiro Rápido ou Sede de Sangue, com 85 de concentração ou quando faltarem poucos segundos para Tiro Quimérico. Tiro Arcano só enquanto você se move; senão, Tiro Firme. Quatro ou mais inimigos: Tiro Quimérico, Tiro Certo instantâneo, Tiro Múltiplo, Tiro Mortal, Armadilha Explosiva. Os mesmos lembretes das outras rotações integradas de Caçador. Se você prefere gastar a concentração de sobra em Tiro Arcano, use a variante de Tiro Arcano."
L["rm.mop.hunter.marksmanship.icyveins.Name"] = "Gastar com Tiro Arcano (Icy Veins)"
L["rm.mop.hunter.marksmanship.icyveins.Description"] = "Uma alternativa à rotação integrada de Precisão, como a Icy Veins, Method, wowtbc.gg e Hekili a jogam: Tiro Certo é lançado normalmente só acima de 80% de vida do alvo ou sob Tiro Rápido ou Sede de Sangue, e a concentração de sobra vai para Tiro Arcano com 60. Concentração Firme é renovada com menos de 4 segundos; contra quatro ou mais inimigos, Tiro Múltiplo vem primeiro. Desativada por padrão: ative-a e desative a rotação integrada de Precisão, ou aumente a prioridade desta."
L["rm.mop.hunter.survival.Name"] = "Recomendada"
L["rm.mop.hunter.survival.Description"] = "Escolhida automaticamente na especialização Sobrevivência. Abre com Marca do Caçador, Flecha Negra e Tiro Explosivo, depois: Tiro Explosivo assim que sair do tempo de recarga e a cada Largar o Dedo, Tiro Mortal, Flecha Negra em alvos que vão sobreviver, seus talentos, Picada de Serpente mantida por Disparo da Naja, Tiro Arcano com 75 de concentração, com Calor da Caçada, ou com 55 quando Flecha Negra não estiver para ficar pronta, depois Disparo da Naja (Tiro Firme antes do nível 81). Dois ou mais inimigos: Tiro Múltiplo primeiro com Largar o Dedo e concentração cheia, Tiro Explosivo em até cinco alvos, Tiro Mortal, Flecha Negra, Armadilha Explosiva a partir de três, Tiro Múltiplo para gastar. Os mesmos lembretes das outras rotações integradas de Caçador; armadilhas para ativações de Largar o Dedo ficam com você."
L["rm.mop.hunter.unspecialized.Name"] = "Antes de uma especialização"
L["rm.mop.hunter.unspecialized.Description"] = "Para os níveis 1 a 9 e qualquer Caçador que não escolheu uma especialização; as rotações integradas de Domínio das Feras, Precisão e Sobrevivência assumem assim que você escolhe uma especialização. Puxa com Marca do Caçador e Tiro Arcano, depois Picada de Serpente em alvos que vão sobreviver, Tiro Múltiplo contra três ou mais inimigos, Tiro Arcano, Tiro Firme e Tiro Automático. Lembra você de chamar, reviver e curar seu ajudante e de manter Aspecto do Falcão ativo."
L["rm.retail.hunter.beastmastery.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.hunter.beastmastery.Description"] = "Recomendada para Domínio das Feras. Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight (ele chama seu ajudante por conta própria); aguarda enquanto você lança ou canaliza. Junto a isso, lembretes do que o Assistente de Combate deixa por sua conta: Derramamento de Sangue e sua habilidade racial em combate, Tiro Retaliatório em um lançamento interrompível, e Lei da Selva sempre que estiver pronta em combate. Lançamentos inimigos ficam ocultos em combate, então a interrupção só acende onde o jogo os exibe; a vida fica oculta no Retail, então decidir quando usar suas defesas (Exaltação e Aspecto da Tartaruga incluídos) é com você. Berloques, Redirecionar e os cuidados com o ajudante ficam com você."
L["rm.retail.hunter.beastmastery.guide.Name"] = "Referência (SimulationCraft e Icy Veins)"
L["rm.retail.hunter.beastmastery.guide.Description"] = "Apenas referência, desativada por padrão: a prioridade otimizada de Domínio das Feras. Cargas, tempos de recarga e ativações ficam ocultos para addons em combate no Midnight, então ela não pode funcionar lá; leia-a ou duplique-a para experimentar. A Concentração fica oculta no Retail. Chama seu ajudante e marca o alvo antes da puxada. Disparo Farpado logo antes de Ira Bestial ou antes de chegar ao limite de cargas; Ira Bestial; Comando para Matar com Uivo do Líder da Alcateia ou Aliado da Natureza, ou livremente enquanto Ira Bestial estiver longe de ficar pronta; Disparo da Naja com Presa da Naja; Disparo da Naja; Disparo Farpado quando não houver Concentração para Disparo da Naja. Patrulheira Sombria: Flecha Negra durante Fogo Devastador e Seta Plangente quando ele terminar. Contra três ou mais inimigos (dois com Cutilada da Fera): Agitação Selvagem para iniciar Cutilada da Fera, depois Comando para Matar, Disparo Farpado e Disparo da Naja enquanto ela durar. Lembretes: Derramamento de Sangue e os lembretes utilitários da rotação integrada do Assistente de Combate."
L["rm.retail.hunter.initial.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.hunter.initial.Description"] = "Recomendada antes de você escolher uma especialização (enquanto o jogo informa a especialização inicial do Caçador). Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, os lembretes que toda rotação integrada de Caçador compartilha, cada um assim que você conhece o feitiço dele. Quando você escolhe uma especialização no nível 10, as rotações integradas dessa especialização assumem."
L["rm.retail.hunter.marksmanship.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.hunter.marksmanship.Description"] = "Recomendada para Precisão. Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, lembretes do que o Assistente de Combate deixa por sua conta: Tiro Certeiro e sua habilidade racial em combate, Tiro Retaliatório em um lançamento interrompível, e Lei da Selva sempre que estiver pronta em combate. Lançamentos inimigos ficam ocultos em combate, então a interrupção só acende onde o jogo os exibe; a vida fica oculta no Retail, então decidir quando usar suas defesas (Exaltação e Aspecto da Tartaruga incluídos) é com você."
L["rm.retail.hunter.marksmanship.guide.Name"] = "Referência (SimulationCraft e Icy Veins)"
L["rm.retail.hunter.marksmanship.guide.Description"] = "Apenas referência, desativada por padrão: a prioridade otimizada de Precisão, que gasta Tiros Precisos antes do próximo Tiro Certo. Ativações e cargas ficam ocultas em combate no Midnight, então ela não pode funcionar lá; a Concentração fica oculta no Retail, então o Tiro Múltiplo com 70 de Concentração contra grupos fica de fora. Marca o alvo e abre com Tiro Certo. Sentinela: Tiro Explosivo, Salva, Tiro Certeiro, Chakram do Luar antes que sua janela acabe, Tiro Certo durante Tiro Certeiro sem Tiros Precisos, Tiro Rápido, Tiro Mortal, Tiro Múltiplo (contra dois inimigos com Aspecto da Hidra) ou Tiro Arcano com Tiros Precisos, Tiro Certo, Chakram do Luar, Tiro Firme. Patrulheira Sombria: Flecha Negra com Tiros Precisos primeiro, nada de Tiro Explosivo durante Largar o Dedo, Tiro Certo antes de chegar ao limite de cargas, Seta Plangente. Contra três ou mais inimigos com Tiros de Mestre: Tiro Explosivo, Salva, Tiro Múltiplo para aplicar Tiros de Mestre, Tiro Certeiro, depois Tiro Rápido e Tiro Certo enquanto ele durar. Decidir usar Tiro Certeiro com 30 acúmulos de Mira Certeira ou contra um alvo sem marca fica com você."
L["rm.retail.hunter.survival.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.hunter.survival.Description"] = "Recomendada para Sobrevivência. Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight (ele chama seu ajudante por conta própria); aguarda enquanto você lança ou canaliza. Junto a isso, lembretes do que o Assistente de Combate deixa por sua conta: Derrubar e sua habilidade racial em combate, Focinheira em um lançamento interrompível, e Lei da Selva sempre que estiver pronta em combate. Lançamentos inimigos ficam ocultos em combate, então a interrupção só acende onde o jogo os exibe; a vida fica oculta no Retail, então decidir quando usar suas defesas (Exaltação e Aspecto da Tartaruga incluídos) é com você."
L["rm.retail.hunter.survival.guide.Name"] = "Referência (SimulationCraft)"
L["rm.retail.hunter.survival.guide.Description"] = "Apenas referência, desativada por padrão: a prioridade de Sobrevivência do SimulationCraft, em que Comando para Matar gera Ponta da Lança, e Derrubar, Cano de Atirar, Bomba de Fogo Indômito e Golpe do Raptor a gastam. Ponta da Lança e cargas ficam ocultas em combate no Midnight, então ela não pode funcionar lá. Chama seu ajudante, marca o alvo e abre com Bomba de Fogo Indômito. Sentinela: Comando para Matar sem Ponta da Lança, Cano de Atirar, Bomba de Fogo Indômito com Marca da Sentinela, Comando para Matar antes de um Derrubar pronto, Derrubar, Chakram do Luar, Golpe do Raptor, depois Comando para Matar, Bomba de Fogo Indômito e Derrubar. Líder da Alcateia: Comando para Matar com Uivo do Líder da Alcateia, depois Derrubar, Bomba de Fogo Indômito, Cano de Atirar e Golpe do Raptor com Ponta da Lança. Contra três ou mais inimigos: Cano de Atirar e Bomba de Fogo Indômito antes de Derrubar, Cortada do Raptor. Lembretes: Aspecto da Águia fora do corpo a corpo e os lembretes utilitários."
L["rm.sod.hunter.melee.Name"] = "Corpo a corpo (SoD)"
L["rm.sod.hunter.melee.Description"] = "Escolhida em um reino da Temporada da Descoberta depois que você grava Ataque Flanqueante, Golpe da Mantícora ou Trinchar e nem Tiro Quimérico nem Tiro Explosivo. Mantém o bônus de Ataque Flanqueante ativo, Mordida de Mangusto com quatro acúmulos de Fúria do Raptor, Golpe da Mantícora com Golpes Espertos, Golpe do Raptor a cada reinício, depois Mordida de Mangusto, Golpe da Mantícora, Ataque Flanqueante e Trinchar; Armadilha Imolante e Cortar Asas só em momentos vazios. Trinchar e Armadilha Explosiva contra três ou mais inimigos; Picada de Serpente e tiros enquanto você não alcança o alvo. Lembretes: Aspecto do Falcão (a versão comum antes do 60), Víbora abaixo de 5% de mana, cuidados com o ajudante (nenhum com Lobo Solitário gravado), Tiro Rápido e habilidades raciais depois que Ataque Flanqueante acumular, Ira Bestial. O posicionamento e os comandos do ajudante ficam com você."
L["rm.sod.hunter.ranged.Name"] = "À distância (SoD)"
L["rm.sod.hunter.ranged.Description"] = "Todo Caçador à distância em um reino da Temporada da Descoberta, do nível 1 ao 60; as runas são usadas depois de gravadas. Picada de Serpente sempre ativa e renovada por Tiro Quimérico. Com a runa de pernas Tiro Mortal: Tiro Múltiplo com quatro Tiros de Mestre, Tiro Mortal durante Tiro Rápido e em alvos na faixa de execução, Tiro Quimérico, depois Armadilha Explosiva e Tiro Arcano enquanto Tiro Múltiplo está em recarga. Sem ela: Tiro Quimérico, Tiro Certo com dois acúmulos de Treinamento de Franco-atirador (sem essa runa, logo após um Tiro Automático), armadilhas pouco antes de Tiro Quimérico ficar pronto (Armadilha Gélida só para alimentar Largar o Dedo), Tiro Explosivo, Tiro Firme, Tiro Múltiplo, Tiro Arcano. Botões corpo a corpo quando um inimigo está perto demais, instantâneos em movimento, armadilhas, Tiro Múltiplo e Salva contra três ou mais inimigos. Lembretes: Falcão, Víbora abaixo de 10% de mana, Coração de Leão, Aura de Tiro Certeiro, cuidados com o ajudante (nenhum com Lobo Solitário gravado), Fogo Concentrado com cinco acúmulos de Frenesi, Tiro Rápido, habilidades raciais e Ira Bestial em elites e em instâncias. Com Largar o Dedo gravado, uma Armadilha Gélida antes da puxada. A intercalação corpo a corpo e o posicionamento ficam com você."
L["rm.tbc.hunter.ranged.simulator.Name"] = "DPS à distância (simulador)"
L["rm.tbc.hunter.ranged.simulator.Description"] = "Níveis 1–70, todas as especializações. Puxa com Marca do Caçador, Tiro Certo e Tiro Automático, mantém o Tiro Automático ativo e usa golpes corpo a corpo quando um alvo chega até você. Antes de Tiro Firme, mantém sua Picada de Serpente ativa e gasta mana em Tiro Certo, Tiro Múltiplo e Tiro Arcano só enquanto tiver bastante. A partir do nível 62: Tiro Múltiplo quando pronto, Tiro Firme logo após cada Tiro Automático, Tiro Arcano para preencher a lacuna, Picada de Serpente quando solo. Com três ou mais inimigos lutando com você, Tiro Múltiplo sempre que estiver pronto. Lembra você dos aspectos (Víbora quando a mana fica baixa, Falcão de novo com metade da mana), cuidados com o ajudante, Comando para Matar, grandes tempos de recarga em elites e chefes e Disparo Silenciador. Comandos do ajudante, Redirecionar, armadilhas, Salva, intercalação corpo a corpo e Fingir de Morto ficam com você."
L["rm.tbc.hunter.ranged.wowhead.Name"] = "DPS à distância (Wowhead)"
L["rm.tbc.hunter.ranged.wowhead.Description"] = "Níveis 1–70, todas as especializações, seguindo os conselhos de raide da Wowhead. A mesma puxada, golpes corpo a corpo, tiros de evolução de nível, Tiro Múltiplo contra vários alvos e lembretes da versão simulador, mas depois de aprender Tiro Firme só oferece Tiro Múltiplo e Tiro Firme após cada Tiro Automático: sem Tiro Arcano como preenchimento (exceto em movimento), sem Picada de Serpente e sem lembrete de Aspecto da Víbora. Comandos do ajudante, Redirecionar, armadilhas, Salva, intercalação corpo a corpo e Fingir de Morto ficam com você. Uma alternativa à rotação integrada de DPS à distância do simulador recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela."
